package org.firstinspires.ftc.teamcode.subsystems;

import com.qualcomm.robotcore.hardware.HardwareMap;
import com.qualcomm.robotcore.hardware.Servo;

import org.firstinspires.ftc.teamcode.config.DeviceNames;
import org.firstinspires.ftc.teamcode.config.Tuned;

// Generated by refract-suite ftc-construct. FLOWER-bottom POLLEN retrieval ramp. Never commanded in INIT
// (R102); it must already be stowed by hand when the robot is placed.
public class Ramp {
    private final Servo servo;
    private boolean deployed = false;

    public Ramp(HardwareMap hardwareMap) {
        servo = hardwareMap.get(Servo.class, DeviceNames.RAMP);
    }

    public static boolean calibrated() {
        return Tuned.isSet(Tuned.rampStowed, Tuned.rampDeployed);
    }

    public boolean toggle() {
        return set(!deployed);
    }

    public boolean set(boolean deploy) {
        if (!calibrated()) return false;
        deployed = deploy;
        servo.setPosition(deploy ? Tuned.rampDeployed : Tuned.rampStowed);
        return true;
    }

    public boolean deployed() {
        return deployed;
    }
}
